FROM jsonb_to_recordset($g2prose$[{"lessonId":"6d81a64d-7f25-4589-9f67-509285762788","lessonTitle":"القراءة: \"صديقتي مريم\"","page":11,"activity_order":4,"activity_type":"multiple_choice","title":"أحدد تفصيلًا من القراءة","section":"practice","prompt":"متى دعت مريم صديقتها نور إلى المذاكرة؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"أرسلت مريم إلى صديقتها نور رسالة تقول فيها: «هل تذاكرين معي بعد العصر؟». وصلت نور في الموعد، وحملت معها قصة قصيرة. قرأت الصديقتان القصة بالتناوب، وسألت كل واحدة الأخرى عن كلمة جديدة. وعندما عجزت نور عن فهم عبارة، شرحتها مريم بهدوء. قالت نور: «الصديقة تساعد صديقتها على التعلم، ولا تكتب واجبها بدلًا منها».","options":["بعد منتصف الليل","بعد العصر","قبل الفجر"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"literal"},"answer":{"correct":"بعد العصر"}},{"lessonId":"6d81a64d-7f25-4589-9f67-509285762788","lessonTitle":"القراءة: \"صديقتي مريم\"","page":11,"activity_order":5,"activity_type":"multiple_choice","title":"أفهم تصرف الشخصية","section":"practice","prompt":"كيف قرأت مريم ونور القصة؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"أرسلت مريم إلى صديقتها نور رسالة تقول فيها: «هل تذاكرين معي بعد العصر؟». وصلت نور في الموعد، وحملت معها قصة قصيرة. قرأت الصديقتان القصة بالتناوب، وسألت كل واحدة الأخرى عن كلمة جديدة. وعندما عجزت نور عن فهم عبارة، شرحتها مريم بهدوء. قالت نور: «الصديقة تساعد صديقتها على التعلم، ولا تكتب واجبها بدلًا منها».","options":["باستخدام الصور فقط","بالتناوب","كلتاهما في صمت دون قراءة"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"comprehension"},"answer":{"correct":"بالتناوب"}},{"lessonId":"6d81a64d-7f25-4589-9f67-509285762788","lessonTitle":"القراءة: \"صديقتي مريم\"","page":11,"activity_order":6,"activity_type":"multiple_choice","title":"أستنتج الدرس المستفاد","section":"practice","prompt":"كيف ساعدت مريم نور عندما لم تفهم عبارة؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"أرسلت مريم إلى صديقتها نور رسالة تقول فيها: «هل تذاكرين معي بعد العصر؟». وصلت نور في الموعد، وحملت معها قصة قصيرة. قرأت الصديقتان القصة بالتناوب، وسألت كل واحدة الأخرى عن كلمة جديدة. وعندما عجزت نور عن فهم عبارة، شرحتها مريم بهدوء. قالت نور: «الصديقة تساعد صديقتها على التعلم، ولا تكتب واجبها بدلًا منها».","options":["أنهت اللقاء دون شرح","شرحت العبارة بهدوء","كتبت واجب نور بدلًا منها"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"inference"},"answer":{"correct":"شرحت العبارة بهدوء"}},{"lessonId":"c732bce6-877a-4da2-948a-0a3a8860862e","lessonTitle":"القراءة: الرياضة غيّرت حياتي براعم العربيّة","page":13,"activity_order":4,"activity_type":"multiple_choice","title":"أحدد تفصيلًا من القراءة","section":"practice","prompt":"كيف اعتادت هدى قضاء الاستراحة قبل نشاط المشي؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"كانت هدى تقضي وقت الاستراحة جالسة كل يوم. اقترحت معلمتها أن تبدأ بالمشي خمس دقائق مع زميلاتها في ساحة المدرسة. في الأسبوع التالي أصبحت هدى تتشوق إلى اللعب، وتختار نشاطًا يناسب قدرتها. قالت لأمها: «لم أصبح بطلة في يوم واحد؛ بدأت بخطوة صغيرة أستطيع تكرارها».","options":["في قاعة المكتبة طوال الوقت","جالسة كل يوم","بالجري ساعة كاملة"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"literal"},"answer":{"correct":"جالسة كل يوم"}},{"lessonId":"c732bce6-877a-4da2-948a-0a3a8860862e","lessonTitle":"القراءة: الرياضة غيّرت حياتي براعم العربيّة","page":13,"activity_order":5,"activity_type":"multiple_choice","title":"أفهم تصرف الشخصية","section":"practice","prompt":"بماذا نصحت المعلمة هدى لتبدأ الحركة؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"كانت هدى تقضي وقت الاستراحة جالسة كل يوم. اقترحت معلمتها أن تبدأ بالمشي خمس دقائق مع زميلاتها في ساحة المدرسة. في الأسبوع التالي أصبحت هدى تتشوق إلى اللعب، وتختار نشاطًا يناسب قدرتها. قالت لأمها: «لم أصبح بطلة في يوم واحد؛ بدأت بخطوة صغيرة أستطيع تكرارها».","options":["التوقف عن كل نشاط","المشي خمس دقائق مع زميلاتها","ممارسة رياضة مرهقة فورًا"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"comprehension"},"answer":{"correct":"المشي خمس دقائق مع زميلاتها"}},{"lessonId":"c732bce6-877a-4da2-948a-0a3a8860862e","lessonTitle":"القراءة: الرياضة غيّرت حياتي براعم العربيّة","page":13,"activity_order":6,"activity_type":"multiple_choice","title":"أستنتج الدرس المستفاد","section":"practice","prompt":"ماذا تعلمت هدى من تجربتها؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"كانت هدى تقضي وقت الاستراحة جالسة كل يوم. اقترحت معلمتها أن تبدأ بالمشي خمس دقائق مع زميلاتها في ساحة المدرسة. في الأسبوع التالي أصبحت هدى تتشوق إلى اللعب، وتختار نشاطًا يناسب قدرتها. قالت لأمها: «لم أصبح بطلة في يوم واحد؛ بدأت بخطوة صغيرة أستطيع تكرارها».","options":["الرياضة غير ممكنة إلا للأبطال","أبدأ بخطوة صغيرة أستطيع تكرارها","يجب أن أصبح بطلة في يوم واحد"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"inference"},"answer":{"correct":"أبدأ بخطوة صغيرة أستطيع تكرارها"}},{"lessonId":"2b83d8bc-a3d7-4ddf-8dc8-3921fc47617a","lessonTitle":"القراءة: الطّائرةُ الورقيّة","page":12,"activity_order":4,"activity_type":"multiple_choice","title":"أحدد تفصيلًا من القراءة","section":"practice","prompt":"من أشرف على صنع خالد للطائرة الورقية؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"صنع خالد طائرة ورقية من ورق خفيف وعيدان آمنة بإشراف والده. رسم عليها سماءً زرقاء ونجمةً ذهبية. خرج إلى مساحة مفتوحة بعيدة عن الطريق والأسلاك. حاول أول مرة، لكن الطائرة لم ترتفع. فحص الخيط وطلب مساعدة والده، ثم جرّب عندما هبّت نسمة مناسبة. ارتفعت الطائرة، فصفق خالد فرحًا.","options":["عامل المطعم","والده","سائق الحافلة"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"literal"},"answer":{"correct":"والده"}},{"lessonId":"2b83d8bc-a3d7-4ddf-8dc8-3921fc47617a","lessonTitle":"القراءة: الطّائرةُ الورقيّة","page":12,"activity_order":5,"activity_type":"multiple_choice","title":"أفهم تصرف الشخصية","section":"practice","prompt":"أين حاول خالد إطلاق الطائرة الورقية؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"صنع خالد طائرة ورقية من ورق خفيف وعيدان آمنة بإشراف والده. رسم عليها سماءً زرقاء ونجمةً ذهبية. خرج إلى مساحة مفتوحة بعيدة عن الطريق والأسلاك. حاول أول مرة، لكن الطائرة لم ترتفع. فحص الخيط وطلب مساعدة والده، ثم جرّب عندما هبّت نسمة مناسبة. ارتفعت الطائرة، فصفق خالد فرحًا.","options":["في طريق السيارات","في مساحة مفتوحة بعيدة عن الطريق والأسلاك","تحت أسلاك الكهرباء"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"comprehension"},"answer":{"correct":"في مساحة مفتوحة بعيدة عن الطريق والأسلاك"}},{"lessonId":"2b83d8bc-a3d7-4ddf-8dc8-3921fc47617a","lessonTitle":"القراءة: الطّائرةُ الورقيّة","page":12,"activity_order":6,"activity_type":"multiple_choice","title":"أستنتج الدرس المستفاد","section":"practice","prompt":"ماذا فعل خالد عندما لم ترتفع الطائرة أول مرة؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"صنع خالد طائرة ورقية من ورق خفيف وعيدان آمنة بإشراف والده. رسم عليها سماءً زرقاء ونجمةً ذهبية. خرج إلى مساحة مفتوحة بعيدة عن الطريق والأسلاك. حاول أول مرة، لكن الطائرة لم ترتفع. فحص الخيط وطلب مساعدة والده، ثم جرّب عندما هبّت نسمة مناسبة. ارتفعت الطائرة، فصفق خالد فرحًا.","options":["صعد إلى مكان خطير","فحص الخيط واستعان بوالده","رماها وتركها"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"inference"},"answer":{"correct":"فحص الخيط واستعان بوالده"}},{"lessonId":"390c85d9-0a67-4296-b256-05687bc7bdaa","lessonTitle":"القراءة: الغذاء الصحيّ براعم العربيّة 80","page":13,"activity_order":4,"activity_type":"multiple_choice","title":"أحدد تفصيلًا من القراءة","section":"practice","prompt":"أي فاكهة وضعت سلمى في حقيبتها؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"فتحت سلمى حقيبة طعامها في المدرسة. وجدت شطيرة منزلية وتفاحة وزجاجة ماء. عرضت زميلتها حلوى، فشكرتها سلمى وقالت: «أحب الحلوى أحيانًا، لكنني أختار اليوم طعامًا متنوعًا». بعد الفسحة شربت الماء، ثم أعادت بقايا الطعام إلى مكانها المناسب وحافظت على نظافة الطاولة.","options":["برتقالة","تفاحة","موزة"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"literal"},"answer":{"correct":"تفاحة"}},{"lessonId":"390c85d9-0a67-4296-b256-05687bc7bdaa","lessonTitle":"القراءة: الغذاء الصحيّ براعم العربيّة 80","page":13,"activity_order":5,"activity_type":"multiple_choice","title":"أفهم تصرف الشخصية","section":"practice","prompt":"كيف تعاملت سلمى مع عرض زميلتها للحلوى؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"فتحت سلمى حقيبة طعامها في المدرسة. وجدت شطيرة منزلية وتفاحة وزجاجة ماء. عرضت زميلتها حلوى، فشكرتها سلمى وقالت: «أحب الحلوى أحيانًا، لكنني أختار اليوم طعامًا متنوعًا». بعد الفسحة شربت الماء، ثم أعادت بقايا الطعام إلى مكانها المناسب وحافظت على نظافة الطاولة.","options":["تركت وجبتها كلها","شكرتها واختارت طعامًا متنوعًا","وبخت زميلتها"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"comprehension"},"answer":{"correct":"شكرتها واختارت طعامًا متنوعًا"}},{"lessonId":"390c85d9-0a67-4296-b256-05687bc7bdaa","lessonTitle":"القراءة: الغذاء الصحيّ براعم العربيّة 80","page":13,"activity_order":6,"activity_type":"multiple_choice","title":"أستنتج الدرس المستفاد","section":"practice","prompt":"ماذا فعلت سلمى بعد الفسحة؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"فتحت سلمى حقيبة طعامها في المدرسة. وجدت شطيرة منزلية وتفاحة وزجاجة ماء. عرضت زميلتها حلوى، فشكرتها سلمى وقالت: «أحب الحلوى أحيانًا، لكنني أختار اليوم طعامًا متنوعًا». بعد الفسحة شربت الماء، ثم أعادت بقايا الطعام إلى مكانها المناسب وحافظت على نظافة الطاولة.","options":["تركت طعامها مفتوحًا","شربت الماء وحافظت على نظافة الطاولة","ألقت البقايا على الأرض"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"inference"},"answer":{"correct":"شربت الماء وحافظت على نظافة الطاولة"}},{"lessonId":"c7e36129-4923-4443-8681-9fb3ffd8e249","lessonTitle":"القراءة: الـمصوّر الصّغير براعم العربيّة","page":12,"activity_order":4,"activity_type":"multiple_choice","title":"أحدد تفصيلًا من القراءة","section":"practice","prompt":"ما الذي أراد عمر تصويره؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"أراد عمر التقاط صورة لطائر في حديقة البيت. اقترب بخطوات هادئة، لكنه تذكر أنه لا ينبغي إزعاج الطيور أو لمس أعشاشها. ابتعد قليلًا واستخدم كاميرا والده بعد استئذانه. انتظر حتى وقف الطائر على غصن منخفض، ثم التقط الصورة. عرضها على أخته وقال: «أجمل الصور ما نحترم فيه الطبيعة».","options":["لوحة داخل الصف","طائرًا في حديقة البيت","سيارة في الطريق"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"literal"},"answer":{"correct":"طائرًا في حديقة البيت"}},{"lessonId":"c7e36129-4923-4443-8681-9fb3ffd8e249","lessonTitle":"القراءة: الـمصوّر الصّغير براعم العربيّة","page":12,"activity_order":5,"activity_type":"multiple_choice","title":"أفهم تصرف الشخصية","section":"practice","prompt":"ماذا فعل عمر كي لا يزعج الطائر؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"أراد عمر التقاط صورة لطائر في حديقة البيت. اقترب بخطوات هادئة، لكنه تذكر أنه لا ينبغي إزعاج الطيور أو لمس أعشاشها. ابتعد قليلًا واستخدم كاميرا والده بعد استئذانه. انتظر حتى وقف الطائر على غصن منخفض، ثم التقط الصورة. عرضها على أخته وقال: «أجمل الصور ما نحترم فيه الطبيعة».","options":["أصدر أصواتًا عالية","ابتعد وانتظر بهدوء","لمس عش الطائر"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"comprehension"},"answer":{"correct":"ابتعد وانتظر بهدوء"}},{"lessonId":"c7e36129-4923-4443-8681-9fb3ffd8e249","lessonTitle":"القراءة: الـمصوّر الصّغير براعم العربيّة","page":12,"activity_order":6,"activity_type":"multiple_choice","title":"أستنتج الدرس المستفاد","section":"practice","prompt":"ما الرسالة التي عبر عنها عمر في نهاية القصة؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"أراد عمر التقاط صورة لطائر في حديقة البيت. اقترب بخطوات هادئة، لكنه تذكر أنه لا ينبغي إزعاج الطيور أو لمس أعشاشها. ابتعد قليلًا واستخدم كاميرا والده بعد استئذانه. انتظر حتى وقف الطائر على غصن منخفض، ثم التقط الصورة. عرضها على أخته وقال: «أجمل الصور ما نحترم فيه الطبيعة».","options":["الاقتراب من الأعشاش دون حذر","احترام الطبيعة أثناء التصوير","إزعاج الطيور للحصول على صور"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"inference"},"answer":{"correct":"احترام الطبيعة أثناء التصوير"}},{"lessonId":"cee27705-fa6c-46b3-9a4f-6a528be12bbf","lessonTitle":"القراءة: تعاون النّمل براعم العربيّة","page":11,"activity_order":4,"activity_type":"multiple_choice","title":"أحدد تفصيلًا من القراءة","section":"practice","prompt":"ماذا كانت تحمل النملة الأولى؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"رأت لينا نملة تحمل حبة طعام أكبر من حجم رأسها. توقفت النملة عند حجر صغير، ثم جاءت نملتان أخريان ودفعتا الحبة من الجانب. سارت النملات نحو العش. قالت لينا: «حين نتعاون في نقل الأدوات الثقيلة داخل الصف ننجز العمل بأمان». لم تلمس لينا الحشرات، واكتفت بالملاحظة من بعيد.","options":["ورقة دفتر","حبة طعام","قطعة خشب كبيرة"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"literal"},"answer":{"correct":"حبة طعام"}},{"lessonId":"cee27705-fa6c-46b3-9a4f-6a528be12bbf","lessonTitle":"القراءة: تعاون النّمل براعم العربيّة","page":11,"activity_order":5,"activity_type":"multiple_choice","title":"أفهم تصرف الشخصية","section":"practice","prompt":"ماذا حدث عند الحجر الصغير؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"رأت لينا نملة تحمل حبة طعام أكبر من حجم رأسها. توقفت النملة عند حجر صغير، ثم جاءت نملتان أخريان ودفعتا الحبة من الجانب. سارت النملات نحو العش. قالت لينا: «حين نتعاون في نقل الأدوات الثقيلة داخل الصف ننجز العمل بأمان». لم تلمس لينا الحشرات، واكتفت بالملاحظة من بعيد.","options":["تحولت الحبة إلى ماء","جاءت نملتان للمساعدة في دفع الحبة","اختفت النملة دون حركة"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"comprehension"},"answer":{"correct":"جاءت نملتان للمساعدة في دفع الحبة"}},{"lessonId":"cee27705-fa6c-46b3-9a4f-6a528be12bbf","lessonTitle":"القراءة: تعاون النّمل براعم العربيّة","page":11,"activity_order":6,"activity_type":"multiple_choice","title":"أستنتج الدرس المستفاد","section":"practice","prompt":"ما الفكرة التي ربطتها لينا بالعمل داخل الصف؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"رأت لينا نملة تحمل حبة طعام أكبر من حجم رأسها. توقفت النملة عند حجر صغير، ثم جاءت نملتان أخريان ودفعتا الحبة من الجانب. سارت النملات نحو العش. قالت لينا: «حين نتعاون في نقل الأدوات الثقيلة داخل الصف ننجز العمل بأمان». لم تلمس لينا الحشرات، واكتفت بالملاحظة من بعيد.","options":["العمل وحدنا في كل أمر","التعاون على حمل الأدوات الثقيلة بأمان","ترك الأدوات على الطريق"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"inference"},"answer":{"correct":"التعاون على حمل الأدوات الثقيلة بأمان"}},{"lessonId":"137e97ee-e49c-4f66-b649-ce147fe0a429","lessonTitle":"القراءة: جولة في محميّة محمّد ب ن زايد الطّبيعيّة براعم العربيّة 42","page":12,"activity_order":4,"activity_type":"multiple_choice","title":"أحدد تفصيلًا من القراءة","section":"practice","prompt":"ماذا قرأ الأطفال عند دخول المنطقة المحمية؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"زارت أسرة عادل منطقة طبيعية محمية في يوم معتدل. قرأ الأطفال اللوحات الإرشادية عند المدخل. شاهدوا نباتات محلية وطيورًا من بعيد، ولم يقطفوا زهرة واحدة. قال الأب: «هذه الأماكن تحمي الكائنات وبيئاتها، ونساعدها عندما نبقي المكان نظيفًا». التقط عادل صورة للوحة ثم دوّن ثلاثة أشياء تعلّمها. هذه حكاية تدريبية خيالية وليست وصفًا لمحمية بعينها.","options":["قائمة الطعام","اللوحات الإرشادية","رسائل الهاتف"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"literal"},"answer":{"correct":"اللوحات الإرشادية"}},{"lessonId":"137e97ee-e49c-4f66-b649-ce147fe0a429","lessonTitle":"القراءة: جولة في محميّة محمّد ب ن زايد الطّبيعيّة براعم العربيّة 42","page":12,"activity_order":5,"activity_type":"multiple_choice","title":"أفهم تصرف الشخصية","section":"practice","prompt":"كيف شاهد الأطفال الطيور والنباتات دون إزعاجها؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"زارت أسرة عادل منطقة طبيعية محمية في يوم معتدل. قرأ الأطفال اللوحات الإرشادية عند المدخل. شاهدوا نباتات محلية وطيورًا من بعيد، ولم يقطفوا زهرة واحدة. قال الأب: «هذه الأماكن تحمي الكائنات وبيئاتها، ونساعدها عندما نبقي المكان نظيفًا». التقط عادل صورة للوحة ثم دوّن ثلاثة أشياء تعلّمها. هذه حكاية تدريبية خيالية وليست وصفًا لمحمية بعينها.","options":["بالاقتراب من الأعشاش ولمسها","من بعيد دون قطف الأزهار","بقطف الأزهار لتجميعها"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"comprehension"},"answer":{"correct":"من بعيد دون قطف الأزهار"}},{"lessonId":"137e97ee-e49c-4f66-b649-ce147fe0a429","lessonTitle":"القراءة: جولة في محميّة محمّد ب ن زايد الطّبيعيّة براعم العربيّة 42","page":12,"activity_order":6,"activity_type":"multiple_choice","title":"أستنتج الدرس المستفاد","section":"practice","prompt":"ما الهدف من المحافظة على المنطقة الطبيعية بحسب الأب؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"زارت أسرة عادل منطقة طبيعية محمية في يوم معتدل. قرأ الأطفال اللوحات الإرشادية عند المدخل. شاهدوا نباتات محلية وطيورًا من بعيد، ولم يقطفوا زهرة واحدة. قال الأب: «هذه الأماكن تحمي الكائنات وبيئاتها، ونساعدها عندما نبقي المكان نظيفًا». التقط عادل صورة للوحة ثم دوّن ثلاثة أشياء تعلّمها. هذه حكاية تدريبية خيالية وليست وصفًا لمحمية بعينها.","options":["إبعاد الزوار عن الدراسة","حماية الكائنات وبيئاتها","تبديل جميع النباتات الصناعية"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"inference"},"answer":{"correct":"حماية الكائنات وبيئاتها"}},{"lessonId":"6c42d72e-4015-4319-98b8-ef06fb0b2d13","lessonTitle":"القراءة: سالمٌ مريض براعم العربيّة","page":11,"activity_order":4,"activity_type":"multiple_choice","title":"أحدد تفصيلًا من القراءة","section":"practice","prompt":"مَن أخبر سالم بأنه يشعر بالتعب؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"استيقظ سالم متعبًا وأخبر والدته أنه لا يشعر بالنشاط المعتاد. قاست والدته حرارته، ثم تواصلت مع الطبيب عند الحاجة. بقي سالم في البيت ليستريح وشرب الماء وفق توجيهات أسرته. اتصل به صديقه حسن وسأله عن حاله، ووعده أن يشرح له ما فاته من الدرس حين يتحسن. شكر سالم صديقه على الاهتمام.","options":["صديقه حسن","والدته","مدير المدرسة"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"literal"},"answer":{"correct":"والدته"}},{"lessonId":"6c42d72e-4015-4319-98b8-ef06fb0b2d13","lessonTitle":"القراءة: سالمٌ مريض براعم العربيّة","page":11,"activity_order":5,"activity_type":"multiple_choice","title":"أفهم تصرف الشخصية","section":"practice","prompt":"ماذا فعلت والدة سالم عندما أخبرها بتعبه؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"استيقظ سالم متعبًا وأخبر والدته أنه لا يشعر بالنشاط المعتاد. قاست والدته حرارته، ثم تواصلت مع الطبيب عند الحاجة. بقي سالم في البيت ليستريح وشرب الماء وفق توجيهات أسرته. اتصل به صديقه حسن وسأله عن حاله، ووعده أن يشرح له ما فاته من الدرس حين يتحسن. شكر سالم صديقه على الاهتمام.","options":["تركته دون متابعة","قاست حرارته وتواصلت مع الطبيب عند الحاجة","طلبت منه اللعب رغم التعب"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"comprehension"},"answer":{"correct":"قاست حرارته وتواصلت مع الطبيب عند الحاجة"}},{"lessonId":"6c42d72e-4015-4319-98b8-ef06fb0b2d13","lessonTitle":"القراءة: سالمٌ مريض براعم العربيّة","page":11,"activity_order":6,"activity_type":"multiple_choice","title":"أستنتج الدرس المستفاد","section":"practice","prompt":"كيف ساعد حسن صديقه سالم؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"استيقظ سالم متعبًا وأخبر والدته أنه لا يشعر بالنشاط المعتاد. قاست والدته حرارته، ثم تواصلت مع الطبيب عند الحاجة. بقي سالم في البيت ليستريح وشرب الماء وفق توجيهات أسرته. اتصل به صديقه حسن وسأله عن حاله، ووعده أن يشرح له ما فاته من الدرس حين يتحسن. شكر سالم صديقه على الاهتمام.","options":["رفض السؤال عنه","اتصل به ووعده بشرح الدروس بعد تحسنه","طلب منه إهمال الدراسة"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"inference"},"answer":{"correct":"اتصل به ووعده بشرح الدروس بعد تحسنه"}},{"lessonId":"a7379987-d16a-4a09-b82e-ee33fc22bb22","lessonTitle":"القراءة: في عيادة العيون براعم العربيّة","page":13,"activity_order":4,"activity_type":"multiple_choice","title":"أحدد تفصيلًا من القراءة","section":"practice","prompt":"ماذا لاحظت منى في الصف؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"لاحظت منى أنها تقترب كثيرًا من السبورة لتقرأ ما عليها. أخبرت أسرتها، فحددت لها موعدًا مع مختص لفحص النظر. في العيادة استمعت منى إلى التعليمات وقرأت بعض الحروف من لوحة الفحص. بعد الزيارة قالت: «حين ألاحظ صعوبة في الرؤية سأخبر شخصًا بالغًا بدل أن أخفي المشكلة».","options":["أن السبورة اختفت","أنها تحتاج إلى الاقتراب من السبورة للقراءة","أنها تسمع أصواتًا جديدة"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"literal"},"answer":{"correct":"أنها تحتاج إلى الاقتراب من السبورة للقراءة"}},{"lessonId":"a7379987-d16a-4a09-b82e-ee33fc22bb22","lessonTitle":"القراءة: في عيادة العيون براعم العربيّة","page":13,"activity_order":5,"activity_type":"multiple_choice","title":"أفهم تصرف الشخصية","section":"practice","prompt":"إلى أين ذهبت منى بعد أن أخبرت أسرتها؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"لاحظت منى أنها تقترب كثيرًا من السبورة لتقرأ ما عليها. أخبرت أسرتها، فحددت لها موعدًا مع مختص لفحص النظر. في العيادة استمعت منى إلى التعليمات وقرأت بعض الحروف من لوحة الفحص. بعد الزيارة قالت: «حين ألاحظ صعوبة في الرؤية سأخبر شخصًا بالغًا بدل أن أخفي المشكلة».","options":["إلى ملعب كرة القدم","إلى مختص لفحص النظر","إلى حديقة الحيوانات"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"comprehension"},"answer":{"correct":"إلى مختص لفحص النظر"}},{"lessonId":"a7379987-d16a-4a09-b82e-ee33fc22bb22","lessonTitle":"القراءة: في عيادة العيون براعم العربيّة","page":13,"activity_order":6,"activity_type":"multiple_choice","title":"أستنتج الدرس المستفاد","section":"practice","prompt":"ما السلوك الذي قررت منى اتباعه إذا صَعُبت عليها الرؤية؟","content":{"origin":"DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030","grade":2,"originalText":"لاحظت منى أنها تقترب كثيرًا من السبورة لتقرأ ما عليها. أخبرت أسرتها، فحددت لها موعدًا مع مختص لفحص النظر. في العيادة استمعت منى إلى التعليمات وقرأت بعض الحروف من لوحة الفحص. بعد الزيارة قالت: «حين ألاحظ صعوبة في الرؤية سأخبر شخصًا بالغًا بدل أن أخفي المشكلة».","options":["تجاهل نصائح المختص","إخبار شخص بالغ بدل إخفاء المشكلة","إخفاء الصعوبة عن الجميع"],"sourceKind":"independent Dadyoom authored graded reading story, not exact or verified Ministry textbook text","objective":"inference"},"answer":{"correct":"إخبار شخص بالغ بدل إخفاء المشكلة"}}]$g2prose$::jsonb)
AS v("lessonId" text,"lessonTitle" text,page int,activity_order int,activity_type text,title text,section text,prompt text,content jsonb,answer jsonb);
DO $guard$
DECLARE eligible integer; inserted integer;
BEGIN
 IF (SELECT count(*) FROM pg_temp.bh_g2_nine_reading_27)<>27
 OR (SELECT count(DISTINCT lesson_id) FROM pg_temp.bh_g2_nine_reading_27)<>9
 OR (SELECT count(DISTINCT (lesson_id,activity_order)) FROM pg_temp.bh_g2_nine_reading_27)<>27
 OR EXISTS(SELECT 1 FROM pg_temp.bh_g2_nine_reading_27 t WHERE
  t.activity_type<>'multiple_choice' OR t.activity_order NOT BETWEEN 4 AND 6
  OR length(t.prompt)<15 OR length(t.content->>'originalText')<170
  OR t.content ? 'correct' OR t.content ? 'answer'
  OR jsonb_array_length(t.content->'options')<>3
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(t.content->'options') o WHERE o=t.answer->>'correct'))
 THEN RAISE EXCEPTION 'Invalid nine story question batch'; END IF;
 SELECT count(DISTINCT l.id) INTO eligible FROM public.lessons l
 JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN public.curricula cu ON cu.id=g.curriculum_id JOIN public.countries co ON co.id=cu.country_id
 JOIN pg_temp.bh_g2_nine_reading_27 t ON t.lesson_id=l.id AND t.lesson_title=l.title AND t.source_page=l.source_page_start
 WHERE l.status='published' AND co.code='BH' AND g.grade_number=2 AND l.source_pdf_url IS NOT NULL
 AND position(t.content->>'originalText' IN l.content)>0
 AND (SELECT count(*) FROM public.lesson_activities a WHERE a.lesson_id=l.id AND a.is_published)=3
 AND (SELECT max(a.activity_order) FROM public.lesson_activities a WHERE a.lesson_id=l.id)=3
 AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities a ON a.id=at.activity_id WHERE a.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id);
 IF eligible<>9 THEN RAISE EXCEPTION 'Exact lesson/body/history scope changed: % / 9',eligible; END IF;
 IF EXISTS(SELECT 1 FROM public.lesson_activities a WHERE a.content->>'origin'='DADYOOM_BH_G2_NINE_READING_STORIES_27_SOURCE_EXACT_20261030')
 THEN RAISE EXCEPTION 'Prevent duplicate nine-lesson append'; END IF;
 INSERT INTO public.lesson_activities(lesson_id,title,activity_type,instructions,content,activity_order,points,is_published,section,prompt,answer,is_required)
 SELECT l.id,t.title,t.activity_type,'اقرأ النص الداعم من ضاديوم وأجب عن السؤال. لا تُنسب هذه القطعة إلى الكتاب الوزاري.',
 t.content,t.activity_order,5,true,t.section,t.prompt,t.answer,false
 FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN public.curricula cu ON cu.id=g.curriculum_id JOIN public.countries co ON co.id=cu.country_id
 JOIN pg_temp.bh_g2_nine_reading_27 t ON t.lesson_id=l.id AND t.lesson_title=l.title AND t.source_page=l.source_page_start
 WHERE co.code='BH' AND g.grade_number=2 AND l.status='published'
 AND position(t.content->>'originalText' IN l.content)>0
 AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities a ON a.id=at.activity_id WHERE a.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>27 THEN RAISE EXCEPTION 'Atomic rollback, inserted % / 27 instead',inserted; END IF;
END $guard$;
COMMIT;